<?php
session_start();
$cfgFile=__DIR__.'/config.php';
if (!file_exists($cfgFile)) { http_response_code(500); exit('Konfigurasi belum dibuat. Salin config.example.php menjadi config.php dan isi kredensial MySQL.'); }
$cfg=require $cfgFile;
try {$pdo=new PDO("mysql:host={$cfg['host']};dbname={$cfg['dbname']};charset=utf8mb4",$cfg['username'],$cfg['password'],[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION,PDO::ATTR_DEFAULT_FETCH_MODE=>PDO::FETCH_ASSOC]);}
catch(Throwable $e){http_response_code(500);exit('Gagal terhubung ke MySQL. Periksa config.php dan detail database InfinityFree.');}
function h($v){return htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');}
function go($p='dashboard'){if(str_contains($p,'&')){$parts=explode('&',$p,2);header('Location: index.php?p='.urlencode($parts[0]).'&'.$parts[1]);}else{header('Location: index.php?p='.urlencode($p));}exit;}
function msg($s,$type='ok'){$_SESSION['flash']=['text'=>$s,'type'=>$type];}
function needLogin(){if(empty($_SESSION['uid']))go('login');}
function needRole($roles){needLogin();if(!in_array($_SESSION['role'],$roles,true)){msg('Akses tidak diizinkan.','err');go('dashboard');}}
function bal($pdo,$id){$s=$pdo->prepare("SELECT COALESCE(SUM(CASE WHEN kind='MASUK' THEN qty ELSE -qty END),0) FROM movements WHERE part_id=?");$s->execute([$id]);return (int)$s->fetchColumn();}
function one($pdo,$sql,$args=[]){$s=$pdo->prepare($sql);$s->execute($args);return $s->fetch();}
function allrows($pdo,$sql,$args=[]){$s=$pdo->prepare($sql);$s->execute($args);return $s->fetchAll();}
function exportCsv($name,$headers,$rows){header('Content-Type: text/csv; charset=UTF-8');header('Content-Disposition: attachment; filename="'.$name.'"');echo "\xEF\xBB\xBF";$o=fopen('php://output','w');fputcsv($o,$headers,';');foreach($rows as $r)fputcsv($o,$r,';');fclose($o);exit;}
$p=$_GET['p']??(empty($_SESSION['uid'])?'login':'dashboard');
if ($_SERVER['REQUEST_METHOD']==='POST') {
 $a=$_POST['action']??'';
 try {
  if($a==='login'){$u=one($pdo,'SELECT * FROM users WHERE username=? AND active=1',[$_POST['username']??'']);if($u&&password_verify($_POST['password']??'',$u['password'])){session_regenerate_id(true);$_SESSION['uid']=$u['id'];$_SESSION['name']=$u['full_name'];$_SESSION['role']=$u['role'];go('dashboard');}msg('Username atau kata sandi salah.','err');go('login');}
  if($a==='logout'){session_unset();session_destroy();header('Location: index.php?p=login');exit;}
  needLogin();
  if($a==='new_repair'){$year=date('Y');$prefix='PR-'.$year.'-';$last=one($pdo,'SELECT req_no FROM repairs WHERE req_no LIKE ? ORDER BY id DESC LIMIT 1',[$prefix.'%']);$n=$last?(int)substr($last['req_no'],-4)+1:1;$no=$prefix.str_pad((string)$n,4,'0',STR_PAD_LEFT);$s=$pdo->prepare('INSERT INTO repairs(req_no,req_date,asset,location,damage,`condition`,created_by,tech_name) VALUES(?,?,?,?,?,?,?,?)');$s->execute([$_POST['req_date'],$_POST['asset'],$_POST['location'],$_POST['damage'],$_POST['condition'],$_POST['created_by'],trim($_POST['tech_name'])]);msg('Permintaan '.$no.' berhasil disimpan.');go('repairs');}
  if($a==='update_repair'){needRole(['admin','teknisi']);$status=$_POST['status'];$finish=$status==='Selesai'&&!empty($_POST['finish_date'])?$_POST['finish_date']:null;$s=$pdo->prepare('UPDATE repairs SET steps=?,status=?,finish_date=?,tech_name=? WHERE id=?');$s->execute([$_POST['steps']??'',$status,$finish,trim($_POST['tech_name']??''),(int)$_POST['rid']]);msg('Laporan perbaikan diperbarui.');go('detail&id='.(int)$_POST['rid']);}
  if($a==='use_part'){needRole(['admin','teknisi']);$rid=(int)$_POST['rid'];$pid=(int)$_POST['part_id'];$qty=(int)$_POST['qty'];if($qty<1)throw new Exception('Jumlah harus lebih dari nol.');$pdo->beginTransaction();$part=one($pdo,'SELECT * FROM parts WHERE id=? AND active=1 FOR UPDATE',[$pid]);if(!$part)throw new Exception('Sparepart tidak ditemukan.');$current=bal($pdo,$pid);if($current<$qty)throw new Exception('Stok '.$part['name'].' tidak cukup. Tersedia '.$current.' '.$part['unit'].'.');$s=$pdo->prepare("INSERT INTO movements(part_id,move_date,kind,qty,repair_id,taken_by,notes) VALUES(?,?,'KELUAR',?,?,?,?)");$s->execute([$pid,$_POST['move_date']?:date('Y-m-d'),$qty,$rid,$_SESSION['name'],$_POST['notes']??'']);$mid=(int)$pdo->lastInsertId();$s=$pdo->prepare('INSERT INTO repair_parts(repair_id,part_id,qty,movement_id) VALUES(?,?,?,?)');$s->execute([$rid,$pid,$qty,$mid]);$pdo->commit();msg('Pemakaian tercatat dan stok otomatis berkurang.');go('detail&id='.$rid);}
  if($a==='add_part'){needRole(['admin']);$s=$pdo->prepare('INSERT INTO parts(code,name,spec,unit,min_stock) VALUES(?,?,?,?,?)');$s->execute([strtoupper(trim($_POST['code'])),trim($_POST['name']),trim($_POST['spec']??''),trim($_POST['unit']?:'pcs'),max(0,(int)$_POST['min_stock'])]);msg('Sparepart ditambahkan. Masukkan saldo awal lewat Barang Masuk.');go('stock');}
  if($a==='edit_part'){needRole(['admin']);$id=(int)$_POST['id'];$pdo->beginTransaction();$old=one($pdo,'SELECT * FROM parts WHERE id=? FOR UPDATE',[$id]);if(!$old)throw new Exception('Barang tidak ditemukan.');$current=bal($pdo,$id);$target=(int)$_POST['stock'];$minimum=(int)$_POST['min_stock'];if($target<0||$minimum<0||trim($_POST['code'])===''||trim($_POST['name'])==='')throw new Exception('Data tidak valid; stok dan minimum tidak boleh negatif.');$s=$pdo->prepare('UPDATE parts SET code=?,name=?,spec=?,unit=?,min_stock=? WHERE id=?');$s->execute([strtoupper(trim($_POST['code'])),trim($_POST['name']),trim($_POST['spec']??''),trim($_POST['unit']?:'pcs'),$minimum,$id]);$delta=$target-$current;if($delta!==0){$s=$pdo->prepare('INSERT INTO movements(part_id,move_date,kind,qty,taken_by,notes) VALUES(?,?,?,?,?,?)');$s->execute([$id,date('Y-m-d'),$delta>0?'MASUK':'KELUAR',abs($delta),$_SESSION['name'],'Koreksi saldo stok oleh admin']);}$pdo->commit();msg('Data sparepart diperbarui; perubahan saldo dicatat di kartu stok.');go('stock');}
  if($a==='stock_in'){needRole(['admin']);$qty=(int)$_POST['qty'];if($qty<1)throw new Exception('Jumlah masuk harus lebih dari nol.');$s=$pdo->prepare("INSERT INTO movements(part_id,move_date,kind,qty,taken_by,notes) VALUES(?,?,'MASUK',?,?,?)");$s->execute([(int)$_POST['part_id'],$_POST['move_date']?:date('Y-m-d'),$qty,$_SESSION['name'],$_POST['notes']??'']);msg('Barang masuk berhasil dicatat.');go('stock');}
  if($a==='add_user'){needRole(['admin']);if(strlen($_POST['password'])<8)throw new Exception('Kata sandi minimal 8 karakter.');$s=$pdo->prepare('INSERT INTO users(username,password,full_name,role) VALUES(?,?,?,?)');$s->execute([trim($_POST['username']),password_hash($_POST['password'],PASSWORD_DEFAULT),trim($_POST['full_name']),$_POST['role']==='admin'?'admin':'teknisi']);msg('Akun berhasil dibuat.');go('users');}
  if($a==='toggle_user'){needRole(['admin']);$id=(int)$_POST['id'];if($id!== (int)$_SESSION['uid'])$pdo->prepare('UPDATE users SET active=1-active WHERE id=?')->execute([$id]);msg('Status akun diperbarui.');go('users');}
 } catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();$txt=$e instanceof PDOException?((string)$e->getCode()==='23000'?'Kode barang atau username sudah digunakan.':'Terjadi kesalahan database. Periksa data yang dimasukkan.'):$e->getMessage();msg($txt,'err');go($a==='login'?'login':($a==='add_user'||$a==='toggle_user'?'users':(str_contains($a,'part')||$a==='stock_in'?'stock':($a==='update_repair'||$a==='use_part'?'detail&id='.(int)($_POST['rid']??0):'repairs'))));}
}
if($p==='export'){needRole(['admin']);$kind=$_GET['kind']??'';if($kind==='repairs'){$rs=allrows($pdo,'SELECT * FROM repairs ORDER BY id');$rows=[];foreach($rs as $r)$rows[]=[$r['req_no'],$r['req_date'],$r['asset'],$r['location'],$r['damage'],$r['condition'],$r['steps'],$r['finish_date'],$r['status'],$r['created_by'],$r['tech_name']];exportCsv('laporan_perbaikan.csv',['Nomor','Tanggal Permintaan','Mesin/Sarana','Lokasi/Bagian','Uraian Kerusakan','Kondisi','Langkah Perbaikan','Tanggal Selesai','Status','Dibuat Oleh','Teknisi'],$rows);}if($kind==='stock'){$rs=allrows($pdo,'SELECT * FROM parts WHERE active=1 ORDER BY name');$rows=[];foreach($rs as $r)$rows[]=[$r['code'],$r['name'],$r['spec'],$r['unit'],bal($pdo,$r['id']),$r['min_stock']];exportCsv('persediaan_sparepart.csv',['Kode','Nama Sparepart','Spesifikasi','Satuan','Stok','Minimum'],$rows);}if($kind==='moves'){$rs=allrows($pdo,'SELECT m.*,p.code,p.name,p.unit,r.req_no FROM movements m JOIN parts p ON p.id=m.part_id LEFT JOIN repairs r ON r.id=m.repair_id ORDER BY m.id');$rows=[];foreach($rs as $r)$rows[]=[$r['move_date'],$r['code'],$r['name'],$r['kind'],$r['qty'],$r['unit'],$r['req_no'],$r['taken_by'],$r['notes']];exportCsv('kartu_stok.csv',['Tanggal','Kode','Sparepart','Jenis','Jumlah','Satuan','Nomor Permintaan','Nama Pengambil','Keterangan'],$rows);}msg('Jenis ekspor tidak dikenal.','err');go('dashboard');}
if($p==='logout'){session_unset();session_destroy();header('Location: index.php?p=login');exit;}
needLogin();
$title='Dashboard';$content='';
if($p==='dashboard'){$title='Dashboard';$total=(int)$pdo->query('SELECT COUNT(*) FROM repairs')->fetchColumn();$opened=(int)$pdo->query("SELECT COUNT(*) FROM repairs WHERE status NOT IN ('Selesai','Dibatalkan')")->fetchColumn();$rr=allrows($pdo,'SELECT * FROM repairs ORDER BY id DESC LIMIT 8');$low=[];foreach(allrows($pdo,'SELECT * FROM parts WHERE active=1 ORDER BY name') as $x){$x['bal']=bal($pdo,$x['id']);if($x['bal']<=$x['min_stock'])$low[]=$x;}}
if($p==='repairs'){$title='Permintaan Perbaikan';$rows=allrows($pdo,'SELECT * FROM repairs ORDER BY id DESC');}
if($p==='new')$title='Permintaan Perbaikan Baru';
if($p==='detail'){$title='Detail Perbaikan';$rid=(int)($_GET['id']??0);$r=one($pdo,'SELECT * FROM repairs WHERE id=?',[$rid]);if(!$r){msg('Permintaan tidak ditemukan.','err');go('repairs');}$parts=allrows($pdo,'SELECT * FROM parts WHERE active=1 ORDER BY name');foreach($parts as &$x)$x['bal']=bal($pdo,$x['id']);unset($x);$used=allrows($pdo,'SELECT rp.qty,p.code,p.name,p.spec,p.unit FROM repair_parts rp JOIN parts p ON p.id=rp.part_id WHERE rp.repair_id=?',[$rid]);}
if($p==='stock'){$title='Kartu Stok Barang';$parts=allrows($pdo,'SELECT * FROM parts WHERE active=1 ORDER BY name');foreach($parts as &$x)$x['bal']=bal($pdo,$x['id']);unset($x);$moves=allrows($pdo,'SELECT m.*,p.code,p.name,p.unit,r.req_no FROM movements m JOIN parts p ON p.id=m.part_id LEFT JOIN repairs r ON r.id=m.repair_id ORDER BY m.id DESC LIMIT 100');}
if($p==='editpart'){$title='Edit Sparepart';$part=one($pdo,'SELECT * FROM parts WHERE id=? AND active=1',[(int)($_GET['id']??0)]);if(!$part){msg('Barang tidak ditemukan.','err');go('stock');}$part['balance']=bal($pdo,$part['id']);}
if($p==='users'){needRole(['admin']);$title='Pengguna';$users=allrows($pdo,'SELECT id,username,full_name,role,active FROM users ORDER BY id');}
function startPage($title){$f=$_SESSION['flash']??null;unset($_SESSION['flash']);echo '<!doctype html><html lang="id"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>'.h($title).' - Administrasi Teknisi</title><style>:root{font-family:Arial,sans-serif;color:#172033;background:#f3f6fb}*{box-sizing:border-box}body{margin:0}.nav{background:#17365d;color:white;padding:14px max(16px,calc((100% - 1180px)/2));display:flex;gap:16px;align-items:center;flex-wrap:wrap}.nav a{color:white;text-decoration:none;font-size:14px}.nav b{margin-right:10px}.wrap{max-width:1180px;margin:26px auto;padding:0 16px}.login{max-width:460px;margin:8vh auto;padding:20px}.panel,.stat{background:white;border:1px solid #e0e6ef;border-radius:12px;padding:20px;margin:16px 0;box-shadow:0 3px 12px #1020400a}.head{display:flex;justify-content:space-between;gap:12px;align-items:center;flex-wrap:wrap}.stats,.grid{display:grid;gap:16px}.stats{grid-template-columns:repeat(3,1fr)}.two{grid-template-columns:repeat(2,minmax(0,1fr))}.stat strong{display:block;font-size:28px;margin-top:10px}.muted,small{color:#697586}.btn,button{display:inline-block;background:#1769aa;color:white;border:0;border-radius:7px;padding:10px 14px;text-decoration:none;cursor:pointer;font-weight:600}.alt{background:#e9eff7;color:#17365d}.actions{display:flex;gap:8px;flex-wrap:wrap}label{display:block;font-size:14px;font-weight:600;margin:12px 0}input,select,textarea{display:block;width:100%;margin-top:6px;padding:10px;border:1px solid #cbd5e1;border-radius:7px;font:inherit;background:#fff}.fields{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:0 14px}.span{grid-column:1/-1}.tablewrap{overflow:auto}table{width:100%;border-collapse:collapse;min-width:650px}th,td{text-align:left;padding:10px;border-bottom:1px solid #e8edf3;vertical-align:top;font-size:14px}th{background:#f7f9fc}.tag{display:inline-block;background:#edf2f8;padding:5px 8px;border-radius:5px;font-size:12px}.Menunggu{background:#fff1ce}.Selesai{background:#d9f5e5}.Diproses{background:#dceeff}.flash{padding:12px;border-radius:8px;margin:12px 0;background:#d9f5e5}.flash.err{background:#ffe1e1;color:#8d1515}.note{padding:12px;background:#fff6d9;border-radius:8px;margin:12px 0}a{color:#155e9a}h1{font-size:27px}h2{font-size:19px}@media(max-width:760px){.two,.stats,.fields{grid-template-columns:1fr}.nav{gap:10px}.wrap{margin-top:16px}.span{grid-column:auto}}</style></head><body>';
 if(!empty($_SESSION['uid']))echo '<div class="nav"><b>⚙ Administrasi Teknisi</b><a href="index.php?p=dashboard">Dashboard</a><a href="index.php?p=repairs">Permintaan Perbaikan</a><a href="index.php?p=new">＋ Permintaan Baru</a><a href="index.php?p=stock">Kartu Stok</a>'.($_SESSION['role']==='admin'?'<a href="index.php?p=users">Pengguna</a>':'').'<a href="index.php?p=logout">Keluar ('.h($_SESSION['name']).')</a></div>';
 echo '<main class="'.(empty($_SESSION['uid'])?'login':'wrap').'">';if($f)echo '<div class="flash '.($f['type']==='err'?'err':'').'">'.h($f['text']).'</div>';}
function endPage(){echo '</main></body></html>';}
startPage($title);
if($p==='login'){echo '<h1>Administrasi Teknisi</h1><p class="muted">Masuk untuk mengelola perbaikan dan stok sparepart.</p><section class="panel"><form method="post"><input type="hidden" name="action" value="login"><label>Username<input name="username" required autocomplete="username"></label><label>Kata sandi<input type="password" name="password" required autocomplete="current-password"></label><button>Masuk</button></form></section><p class="muted">Untuk keamanan, ganti kata sandi awal setelah login.</p>';}
elseif($p==='dashboard'){echo '<div class="head"><div><h1>Dashboard</h1><span class="muted">Ringkasan pekerjaan dan persediaan.</span></div><a class="btn" href="index.php?p=new">＋ Permintaan Baru</a></div><div class="stats"><div class="stat">Total permintaan<strong>'.$total.'</strong></div><div class="stat">Belum selesai<strong>'.$opened.'</strong></div><div class="stat">Stok menipis<strong>'.count($low).'</strong></div></div><div class="grid two"><section class="panel"><h2>Permintaan terbaru</h2><div class="tablewrap"><table><tr><th>Nomor</th><th>Mesin</th><th>Status</th></tr>';foreach($rr as $r)echo '<tr><td><a href="index.php?p=detail&id='.$r['id'].'">'.h($r['req_no']).'</a></td><td>'.h($r['asset']).'</td><td><span class="tag">'.h($r['status']).'</span></td></tr>';if(!$rr)echo '<tr><td colspan="3">Belum ada permintaan.</td></tr>';echo '</table></div></section><section class="panel"><h2>Stok menipis</h2>';foreach($low as $x)echo '<p><b>'.h($x['name']).'</b> — '.$x['bal'].' '.h($x['unit']).' <small>(minimum '.$x['min_stock'].')</small></p>';if(!$low)echo '<p class="muted">Belum ada peringatan stok.</p>';echo '</section></div>';if($_SESSION['role']==='admin')echo '<section class="panel"><h2>Ekspor laporan (CSV, bisa dibuka di Excel)</h2><div class="actions"><a class="btn alt" href="index.php?p=export&kind=repairs">Laporan perbaikan</a><a class="btn alt" href="index.php?p=export&kind=stock">Persediaan</a><a class="btn alt" href="index.php?p=export&kind=moves">Kartu stok</a></div></section>';}
elseif($p==='repairs'){echo '<div class="head"><h1>Permintaan Perbaikan</h1><a class="btn" href="index.php?p=new">＋ Buat Permintaan</a></div><section class="panel tablewrap"><table><tr><th>Nomor</th><th>Tanggal</th><th>Mesin</th><th>Lokasi</th><th>Teknisi</th><th>Status</th></tr>';foreach($rows as $r)echo '<tr><td><a href="index.php?p=detail&id='.$r['id'].'">'.h($r['req_no']).'</a></td><td>'.h($r['req_date']).'</td><td>'.h($r['asset']).'</td><td>'.h($r['location']).'</td><td>'.h($r['tech_name']?:'Belum ditugaskan').'</td><td>'.h($r['status']).'</td></tr>';if(!$rows)echo '<tr><td colspan="6">Belum ada permintaan.</td></tr>';echo '</table></section>';}
elseif($p==='new'){echo '<h1>Form Permintaan Perbaikan</h1><section class="panel"><form method="post"><input type="hidden" name="action" value="new_repair"><div class="fields"><label>Tanggal permintaan *<input type="date" name="req_date" value="'.date('Y-m-d').'" required></label><label>Nama mesin/sarana/prasarana *<input name="asset" required></label><label>Lokasi/bagian *<input name="location" required></label><label>Kondisi terakhir *<select name="condition"><option>Mati total</option><option>Rusak</option><option>Tidak tahan lama</option></select></label><label class="span">Uraian kerusakan *<textarea name="damage" rows="4" required></textarea></label><label>Dibuat oleh *<input name="created_by" value="'.h($_SESSION['name']).'" required></label><label>Diterima oleh teknisi *<input name="tech_name" placeholder="Masukkan nama teknisi" required></label></div><button>Simpan Permintaan</button></form></section>';}
elseif($p==='detail'){echo '<div class="head"><div><h1>'.h($r['req_no']).'</h1><span class="muted">'.h($r['asset']).' · '.h($r['location']).'</span></div><span class="tag">'.h($r['status']).'</span></div><div class="grid two"><section class="panel"><h2>Informasi permintaan</h2><p><b>Tanggal:</b> '.h($r['req_date']).'</p><p><b>Mesin/fasilitas:</b> '.h($r['asset']).'</p><p><b>Lokasi:</b> '.h($r['location']).'</p><p><b>Kondisi:</b> '.h($r['condition']).'</p><p><b>Kerusakan:</b><br>'.nl2br(h($r['damage'])).'</p><p><b>Dibuat oleh:</b> '.h($r['created_by']).'</p><p><b>Teknisi:</b> '.h($r['tech_name']?:'Belum ditugaskan').'</p><p><b>Tanggal selesai:</b> '.h($r['finish_date']?:'Belum selesai').'</p></section><section class="panel"><h2>Perbarui pekerjaan</h2><form method="post"><input type="hidden" name="action" value="update_repair"><input type="hidden" name="rid" value="'.$r['id'].'"><label>Diterima oleh teknisi<input name="tech_name" value="'.h($r['tech_name']).'" required></label><label>Langkah perbaikan<textarea name="steps" rows="4">'.h($r['steps']).'</textarea></label><label>Status<select name="status">';foreach(['Menunggu','Diproses','Selesai','Dibatalkan'] as $s)echo '<option '.($r['status']===$s?'selected':'').'>'.$s.'</option>';echo '</select></label><label>Tanggal selesai<input type="date" name="finish_date" value="'.h($r['finish_date']).'"></label><button>Simpan perubahan</button></form></section></div><section class="panel"><h2>Sparepart yang digunakan</h2>';foreach($used as $u)echo '<p>'.h($u['code']).' — <b>'.h($u['name']).'</b> · '.$u['qty'].' '.h($u['unit']).' '.($u['spec']?'('.h($u['spec']).')':'').'</p>';if(!$used)echo '<p class="muted">Belum ada sparepart yang digunakan.</p>';echo '<hr><h2>Catat penggunaan sparepart</h2><form method="post"><input type="hidden" name="action" value="use_part"><input type="hidden" name="rid" value="'.$r['id'].'"><div class="fields"><label>Sparepart<select name="part_id" required><option value="">Pilih sparepart</option>';foreach($parts as $x)echo '<option value="'.$x['id'].'" '.($x['bal']<1?'disabled':'').'>'.h($x['code'].' — '.$x['name'].' (stok '.$x['bal'].' '.$x['unit'].')').'</option>';echo '</select></label><label>Jumlah digunakan<input type="number" name="qty" min="1" required></label><label>Tanggal digunakan<input type="date" name="move_date" value="'.date('Y-m-d').'"></label><label>Keterangan<input name="notes" placeholder="Penggantian komponen"></label></div><button>Catat pemakaian & kurangi stok</button></form></section>';}
elseif($p==='stock'){if($_SESSION['role']==='admin'){echo '<div class="grid two"><section class="panel"><h2>Tambah sparepart</h2><form method="post"><input type="hidden" name="action" value="add_part"><label>Kode barang *<input name="code" required></label><label>Nama sparepart *<input name="name" required></label><label>Spesifikasi<input name="spec"></label><div class="fields"><label>Satuan<input name="unit" value="pcs"></label><label>Stok minimum<input name="min_stock" type="number" min="0" value="0"></label></div><button>Tambah barang</button></form></section><section class="panel"><h2>Barang masuk / stok awal</h2><form method="post"><input type="hidden" name="action" value="stock_in"><label>Sparepart<select name="part_id" required><option value="">Pilih barang</option>';foreach($parts as $x)echo '<option value="'.$x['id'].'">'.h($x['code'].' — '.$x['name'].' (stok '.$x['bal'].')').'</option>';echo '</select></label><div class="fields"><label>Tanggal masuk<input type="date" name="move_date" value="'.date('Y-m-d').'"></label><label>Jumlah masuk<input type="number" name="qty" min="1" required></label></div><label>Keterangan<input name="notes"></label><button>Catat barang masuk</button></form></section></div>';}echo '<section class="panel tablewrap"><h2>Daftar persediaan</h2><table><tr><th>Kode</th><th>Nama</th><th>Spesifikasi</th><th>Satuan</th><th>Stok</th><th>Minimum</th><th>Status</th>'.($_SESSION['role']==='admin'?'<th>Aksi</th>':'').'</tr>';foreach($parts as $x)echo '<tr><td>'.h($x['code']).'</td><td><b>'.h($x['name']).'</b></td><td>'.h($x['spec']?:'—').'</td><td>'.h($x['unit']).'</td><td><b>'.$x['bal'].'</b></td><td>'.$x['min_stock'].'</td><td>'.($x['bal']<=$x['min_stock']?'Menipis':'Aman').'</td>'.($_SESSION['role']==='admin'?'<td><a class="btn alt" href="index.php?p=editpart&id='.$x['id'].'">Edit</a></td>':'').'</tr>';if(!$parts)echo '<tr><td colspan="8">Belum ada barang.</td></tr>';echo '</table></section><section class="panel tablewrap"><h2>Transaksi stok terbaru</h2><table><tr><th>Tanggal</th><th>Barang</th><th>Jenis</th><th>Jumlah</th><th>No. permintaan</th><th>Pencatat</th><th>Keterangan</th></tr>';foreach($moves as $m)echo '<tr><td>'.h($m['move_date']).'</td><td>'.h($m['code'].' — '.$m['name']).'</td><td>'.h($m['kind']).'</td><td>'.$m['qty'].' '.h($m['unit']).'</td><td>'.h($m['req_no']?:'—').'</td><td>'.h($m['taken_by']).'</td><td>'.h($m['notes']).'</td></tr>';if(!$moves)echo '<tr><td colspan="7">Belum ada transaksi.</td></tr>';echo '</table></section>';}
elseif($p==='editpart'){needRole(['admin']);echo '<h1>Edit Sparepart</h1><section class="panel"><p class="note">Perubahan stok akan dicatat sebagai transaksi koreksi di kartu stok.</p><form method="post"><input type="hidden" name="action" value="edit_part"><input type="hidden" name="id" value="'.$part['id'].'"><div class="fields"><label>Kode barang<input name="code" value="'.h($part['code']).'" required></label><label>Nama sparepart<input name="name" value="'.h($part['name']).'" required></label><label class="span">Spesifikasi<input name="spec" value="'.h($part['spec']).'"></label><label>Satuan<input name="unit" value="'.h($part['unit']).'" required></label><label>Stok minimum<input type="number" name="min_stock" min="0" value="'.$part['min_stock'].'" required></label><label>Stok saat ini<input type="number" name="stock" min="0" value="'.$part['balance'].'" required></label></div><button>Simpan perubahan</button> <a class="btn alt" href="index.php?p=stock">Batal</a></form></section>';}
elseif($p==='users'){echo '<h1>Pengguna</h1><div class="grid two"><section class="panel"><h2>Tambah akun</h2><form method="post"><input type="hidden" name="action" value="add_user"><label>Nama lengkap<input name="full_name" required></label><label>Username<input name="username" required></label><label>Kata sandi (minimal 8 karakter)<input type="password" name="password" minlength="8" required></label><label>Peran<select name="role"><option value="teknisi">Teknisi</option><option value="admin">Admin</option></select></label><button>Buat akun</button></form></section><section class="panel tablewrap"><h2>Daftar pengguna</h2><table><tr><th>Nama</th><th>Username</th><th>Peran</th><th>Status</th><th>Aksi</th></tr>';foreach($users as $u)echo '<tr><td>'.h($u['full_name']).'</td><td>'.h($u['username']).'</td><td>'.h($u['role']).'</td><td>'.($u['active']?'Aktif':'Nonaktif').'</td><td>'.((int)$u['id']!==(int)$_SESSION['uid']?'<form method="post"><input type="hidden" name="action" value="toggle_user"><input type="hidden" name="id" value="'.$u['id'].'"><button class="alt">Aktif/nonaktif</button></form>':'—').'</td></tr>';echo '</table></section></div>';}
else {echo '<h1>Halaman tidak ditemukan</h1><a href="index.php?p=dashboard">Kembali ke dashboard</a>';}
endPage();
